const base = $input.item.json;
// Build structured files for HTML generation
const files = [
  { name: 'User_Guide', content: base.guide, title: base.brand_name + ' - Complete Guide' },
  { name: 'Prompt_Library', content: base.prompts, title: base.brand_name + ' - Prompt Library' },
  { name: 'Bonus_Checklist', content: base.checklist, title: base.brand_name + ' - Checklist' },
  { name: 'Resources', content: base.resources, title: base.brand_name + ' - Resources' },
  { name: 'Bonus', content: base.bonus, title: base.brand_name + ' - Bonus' },
  { name: 'START_HERE', content: `# START HERE - ${base.brand_name}\n\nWelcome to ${base.brand_name}!\n\nOutcome: ${base.dream_outcome}\nAvatar: ${base.avatar}\n\nQuick Start: Read this, open checklist, implement module 1 quick win.`, title: 'START HERE - ' + base.brand_name }
];
// generate simple HTML from markdown (marked equivalent via regex for n8n no deps)
function mdToHtml(md){ return md.replace(/^# (.*)$/gm,'<h1>$1</h1>').replace(/^## (.*)$/gm,'<h2>$1</h2>').replace(/^### (.*)$/gm,'<h3>$1</h3>').replace(/\*\*(.*?)\*\*/g,'<strong>$1</strong>').replace(/\n/g,'<br/>'); }
const htmlTemplate = (content, title) => `<!DOCTYPE html><html><head><meta charset='UTF-8'><title>${title}</title><style>body{font-family:Inter,sans-serif;max-width:800px;margin:0 auto;padding:40px;line-height:1.7;color:#0f172a}h1{font-size:32px;border-bottom:3px solid #6366f1;padding-bottom:12px}h2{font-size:24px;margin:30px 0 10px}h3{font-size:18px}pre{background:#0f172a;color:#e2e8f0;padding:20px;border-radius:12px}blockquote{border-left:4px solid #6366f1;padding:12px 20px;background:#f8fafc;border-radius:8px}</style></head><body><h1>${title}</h1>${mdToHtml(content)}<footer style='margin-top:60px;border-top:1px solid #e2e8f0;text-align:center;color:#64748b;font-size:12px'>Premium Product | ${base.brand_name} | 2026</footer></body></html>`;
return files.map(f=>({ json: { ...base, file_name: f.name, html: htmlTemplate(f.content, f.title), markdown: f.content, title: f.title } }));

const first = $input.first().json;
// return base for next workflow
return [{ json: { ...first, processed_files: $input.all.map(i=>i.json.file_name) } }];
